CREATE TABLE Chessboard (
    Chessboard_ID INTEGER PRIMARY KEY,
    Chessboard_Name VARCHAR(255)
);

CREATE TABLE Quality_Inspection_Model (
    Model_ID INTEGER PRIMARY KEY,
    Model_Result VARCHAR(255),
    Running_Time FLOAT
);

CREATE TABLE Chess_Piece (
    Belonging_Chessboard INTEGER NOT NULL,
    Chess_Piece_ID INTEGER PRIMARY KEY,
    Color VARCHAR(255),
    Position VARCHAR(255),
    FOREIGN KEY (Belonging_Chessboard) REFERENCES Chessboard(Chessboard_ID)
);

CREATE TABLE Quality_Inspection (
    Chess_Piece_ID INTEGER NOT NULL,
    Inspection_ID INTEGER PRIMARY KEY,
    Inspection_Result VARCHAR(255),
    Inspection_Time DATETIME,
    FOREIGN KEY (Chess_Piece_ID) REFERENCES Chess_Piece(Chess_Piece_ID)
);

CREATE TABLE Quality_Alert (
    Alert_ID INTEGER PRIMARY KEY,
    Defect_Type VARCHAR(255),
    Inspection_ID INTEGER NOT NULL,
    FOREIGN KEY (Inspection_ID) REFERENCES Quality_Inspection(Inspection_ID)
);
